import java.util.Scanner;

public class TitleCaseConverter {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        System.out.println("Enter a sentence:");
        String s = sc.nextLine().trim() + " ";

        String word = "";
        String titleCaseSentence = "";

        for (int i = 0; i < s.length(); i++) {
            char ch = s.charAt(i);
            if (ch != ' ') {
                word = word + ch;
            } else {
                if (word.length() > 0) {
                    String formattedWord = Character.toUpperCase(word.charAt(0)) + 
                                           word.substring(1).toLowerCase();
                    titleCaseSentence = titleCaseSentence + formattedWord + " ";
                }
                word = "";
            }
        }

        System.out.println("Title Case Sentence:");
        System.out.println(titleCaseSentence.trim());
    }
}
/*
VARIABLE DESCRIPTION TABLE:
Variable Name      | Data Type | Purpose
s                  | String    | Input sentence with trailing space
word               | String    | Accumulates extracted word
titleCaseSentence  | String    | Resultant sentence in Title Case
formattedWord      | String    | Current word with initial letter capitalized
i                  | int       | Loop index
ch                 | char      | Extracted character at index i
*/
